window.WOLFIE_CONTEXT_PACKS=(window.WOLFIE_CONTEXT_PACKS||[]).concat([{"id":"mission-v2-009","day":9,"level":"A2","title":"A picnic with a backup plan","ru":"Пикник с запасным планом","goal":"Договориться о встрече на природе и согласовать запасной вариант.","version":1,"quality":"authored-not-independently-reviewed","grammar":{"title":"Be going to for plans and visible evidence","rule":"Be going to + начальная форма выражает намерение или прогноз на основании того, что наблюдаем. Согласуй am/is/are с подлежащим. Для вопроса поставь be перед подлежащим.","pattern":"We're going to have a picnic; It's going to rain.","example":"Are you going to bring a blanket?","pitfall":"Не пропускай be и не ставь -ing после going to.","exercises":[["choice","We ___ going to meet near the lake.",["are","is","do"],0,"We are."],["type","Complete: It is going to ___ (rain).",["rain"],"Going to + base verb."],["order","Составь: Мы собираемся взять одеяло.",["blanket","a","take","to","going","are","We"],"We are going to take a blanket","Use are going to."],["choice","___ you going to bring lunch?",["Are","Do","Is"],0,"Move are before you."],["type","Complete: She ___ (be) going to bring fruit.",["is"],"She is."],["order","Составь: Я не собираюсь ехать один.",["alone","travel","to","going","not","am","I"],"I am not going to travel alone","Place not after am."]]},"words":[["a picnic blanket","одеяло для пикника"],["a sheltered bench","скамейка под навесом"],["a picnic basket","корзина для пикника"],["a weather forecast","прогноз погоды"],["a waterproof jacket","непромокаемая куртка"],["a backup location","запасное место"],["a reusable bottle","многоразовая бутылка"],["a cloudy sky","облачное небо"],["a light shower","небольшой дождь"],["a meeting spot","место встречи"]],"phrases":[["We're going to meet by the lake.","Мы собираемся встретиться у озера."],["Are you going to bring something to eat?","Ты собираешься принести что-нибудь поесть?"],["The sky looks quite dark.","Небо выглядит довольно тёмным."],["Let's choose a place with a shelter.","Выберем место с навесом."],["I'll bring a spare jacket.","Я возьму запасную куртку."],["If it rains, we can meet indoors.","Если пойдёт дождь, можем встретиться в помещении."],["We don't need to cancel yet.","Пока не нужно отменять."],["Can you bring a reusable bottle?","Можешь взять многоразовую бутылку?"],["I'll confirm the plan in the morning.","Утром подтвержу план."],["The café is our backup location.","Кафе — наше запасное место."]],"reading":{"title":"A picnic with a backup plan","paragraphs":["A group of friends is going to have a picnic on Sunday. They choose a quiet place beside a lake and agree to meet at eleven. Nina is going to bring fruit, and Leo plans to bring sandwiches. Tom offers to take a large blanket. On Saturday evening, the weather forecast shows a chance of rain. The friends do not want to cancel their meeting immediately, because the forecast may change overnight.","They choose a café near the park as a backup location. If the sky is clear in the morning, they are going to follow the original plan. If it is raining, they will meet inside the café instead. Nina sends one message with both locations and asks everyone to check it before leaving home. Nobody has to guess where the others will be."],"questions":[["When do the friends plan to meet?",["Ten","Eleven","Twelve"],1],["What will Leo bring?",["Fruit","A blanket","Sandwiches"],2],["What is the backup location?",["A café","A bus","A shop"],0],["When will they check the weather again?",["On Monday","On Sunday morning","A week later"],1]]},"dialogue":[["Nina","We're going to meet by the lake at eleven.","Мы собираемся встретиться у озера в одиннадцать."],["Leo","Are you going to bring fruit?","Ты собираешься принести фрукты?"],["Nina","Yes, and Tom is bringing a blanket.","Да, а Том принесёт одеяло."],["Leo","The forecast says it may rain.","Прогноз говорит, что возможен дождь."],["Nina","Let's choose a backup location.","Давай выберем запасное место."],["Leo","How about the café near the park?","Как насчёт кафе возле парка?"],["Nina","Great. I'll confirm the plan in the morning.","Отлично. Подтвержу план утром."],["Leo","I'll check your message before I leave.","Проверю твоё сообщение перед выходом."]],"listening":["When will Nina confirm the plan?",["This evening","In the morning","Next week"],1],"speaking":["Describe a picnic plan using three going-to sentences.","Ask a friend what they are going to bring.","Explain a backup meeting location if the weather changes.","Describe the weather you can see from a fictional window.","Role-play confirming both meeting locations clearly."],"writing":["Write a picnic invitation with time, place and items to bring.","Write a message giving a backup plan for rain.","Write a morning confirmation of one of two previously agreed locations."],"model":"Hi everyone! We're going to meet by the lake at eleven. Please bring something to eat and a bottle of water. If it rains, we'll meet at the café near the park instead. I'll confirm the location in the morning.","profile":"extended-v1"},{"id":"mission-v2-039","day":39,"level":"A2","title":"A museum ticket for the wrong day","ru":"Билет в музей на другой день","goal":"Проверить дату и время посещения, объяснить ошибку и попросить изменить билет.","version":1,"quality":"authored-not-independently-reviewed","grammar":{"title":"Dates, times and prepositions","rule":"On употребляется с днями и конкретными датами; at — с точным временем; in — с месяцами, годами и частями дня. В выражениях next Friday, this morning, tomorrow предлог обычно не нужен.","pattern":"on Friday; at 10:30; in May","example":"Our tickets are for Saturday at two.","pitfall":"Не говори on tomorrow.","exercises":[["choice","The museum visit is ___ Saturday.",["on","at","in"],0,"On + day."],["type","Complete: Our entry time is ___ eleven thirty.",["at"],"At + clock time."],["order","Составь: Билет на пятницу.",["Friday","for","is","ticket","The"],"The ticket is for Friday","For indicates the intended day."],["choice","The exhibition opens ___ June.",["in","on","at"],0,"In + month."],["type","Complete: I want to visit ___ (tomorrow/on tomorrow).",["tomorrow"],"Tomorrow takes no preposition."],["order","Составь: Мы встречаемся во вторник в три.",["three","at","Tuesday","on","meeting","are","We"],"We are meeting on Tuesday at three","On + day, at + time."]]},"words":[["an admission ticket","входной билет"],["a timed entry","вход в назначенное время"],["a booking confirmation","подтверждение бронирования"],["a calendar date","календарная дата"],["a ticket counter","билетная касса"],["an available time slot","свободный временной интервал"],["a permanent exhibition","постоянная выставка"],["a temporary exhibition","временная выставка"],["a booking reference","номер бронирования"],["a date change","изменение даты"]],"phrases":[["My ticket is for the wrong date.","Мой билет на неправильную дату."],["Is it possible to change the booking?","Можно изменить бронирование?"],["Our visit was meant to be on Sunday.","Мы собирались прийти в воскресенье."],["What time slots are still available?","Какие интервалы ещё доступны?"],["Here is my booking confirmation.","Вот подтверждение бронирования."],["Could you check the reference number?","Можете проверить номер бронирования?"],["The afternoon slot would work for us.","Дневной интервал нам подходит."],["Is there a separate ticket for the exhibition?","На выставку нужен отдельный билет?"],["Please confirm the new date in writing.","Подтвердите новую дату письменно."],["I'll check the date before I leave.","Проверю дату перед уходом."]],"reading":{"title":"A museum ticket for the wrong day","paragraphs":["Rosa and her cousin buy two museum tickets online. They want to visit on Sunday afternoon, but Rosa accidentally selects Saturday. She notices the mistake when she checks the confirmation email on Friday. The email shows the date, the entry time and a booking reference. Rosa does not buy new tickets immediately because she wants to know whether the original booking can be changed.","She contacts the museum ticket office and explains the mistake. The assistant checks the reference and says that two places are available at three on Sunday. Rosa agrees to the new time. The assistant sends an updated confirmation, and Rosa checks that the date, time and number of visitors are correct. She then forwards the new details to her cousin."],"questions":[["Which day did Rosa select by mistake?",["Friday","Saturday","Sunday"],1],["When does she notice the error?",["On Friday","On Monday","At the museum entrance"],0],["What new time is available?",["Two","Four","Three"],2],["What does Rosa check in the updated confirmation?",["Only the price","Date, time and visitor count","The weather forecast"],1]]},"dialogue":[["Rosa","Hello. My ticket is for Saturday, but I need Sunday.","Здравствуйте. Мой билет на субботу, а мне нужно воскресенье."],["Assistant","Could you give me the booking reference?","Можете назвать номер бронирования?"],["Rosa","Yes. Here is the confirmation email.","Да. Вот письмо с подтверждением."],["Assistant","We have two places at three on Sunday.","У нас есть два места в воскресенье в три."],["Rosa","That time works for us.","Это время нам подходит."],["Assistant","I'll send an updated confirmation.","Отправлю обновлённое подтверждение."],["Rosa","Thank you. Is the exhibition included?","Спасибо. Выставка входит в билет?"],["Assistant","Yes, it is included in this booking.","Да, она входит в это бронирование."]],"listening":["What new time is offered?",["Three on Sunday","Two on Saturday","Four on Friday"],0],"speaking":["Explain a fictional booking mistake using on and at.","Ask which time slots are available.","Repeat a date and time to confirm you understood.","Ask whether a temporary exhibition is included in a ticket.","Role-play checking the corrected confirmation before agreeing."],"writing":["Write a museum ticket change request.","Write a confirmation message to a friend with the new date and time.","Write a list of four details to check on a fictional booking."],"model":"Hello, my booking is for Saturday at two, but I meant to select Sunday. Could you change it to Sunday afternoon for two visitors? My booking reference is EXAMPLE-123. Please confirm the new date and time.","profile":"extended-v1"},{"id":"mission-v2-069","day":69,"level":"A2","title":"Meeting a friend's family","ru":"Знакомство с семьёй друга","goal":"Представиться, рассказать о себе и задавать ненавязчивые вопросы.","version":1,"quality":"authored-not-independently-reviewed","grammar":{"title":"Present simple questions and short answers","rule":"В Present Simple с I/you/we/they используется do, с he/she/it — does. После does глагол без -s. Краткие ответы: Yes, I do; No, she doesn't.","pattern":"Do you live nearby? Does your sister study here?","example":"Yes, I do. No, she doesn't.","pitfall":"Не говори Does she works.","exercises":[["choice","___ your brother live nearby?",["Does","Do","Is do"],0,"Does + singular third person."],["type","Complete: Does she ___ (work) here?",["work"],"Use the base verb after does."],["order","Составь: Ты часто сюда приходишь?",["here","come","often","you","Do"],"Do you often come here","Do + subject + base verb."],["choice","Do you enjoy cooking? Yes, I ___.",["do","does","am"],0,"Use do in the short answer."],["type","Complete: Does he play tennis? No, he ___.",["doesn't"],"Use doesn't in the negative short answer."],["order","Составь: Где учится твоя сестра?",["study","sister","your","does","Where"],"Where does your sister study","Question word + does + subject + base verb."]]},"words":[["a family gathering","семейная встреча"],["a first introduction","первое знакомство"],["a family friend","друг семьи"],["a younger cousin","младший двоюродный брат или сестра"],["a shared hobby","общее увлечение"],["a friendly greeting","дружелюбное приветствие"],["a conversation starter","способ начать разговор"],["a weekend activity","занятие на выходных"],["a polite question","вежливый вопрос"],["a common interest","общий интерес"]],"phrases":[["It's nice to meet you at last.","Наконец-то приятно познакомиться."],["I've heard a lot about you.","Я много о вас слышал."],["Do you live nearby?","Вы живёте поблизости?"],["What do you like doing at weekends?","Чем вы любите заниматься по выходным?"],["I enjoy taking photos in my free time.","В свободное время люблю фотографировать."],["Does your brother play any sports?","Твой брат занимается спортом?"],["We have that in common.","У нас есть это общее."],["Would you like to tell me about your hobby?","Хотите рассказать о своём увлечении?"],["It's been lovely talking to you.","Было приятно с вами поговорить."],["Thanks for making me feel welcome.","Спасибо за тёплый приём."]],"reading":{"title":"Meeting a friend's family","paragraphs":["Ben is visiting his friend Ana's family for the first time. He feels a little nervous because he does not know the other guests. Ana introduces him to her aunt and two cousins. Ben says that it is nice to meet them and asks whether they live nearby. One cousin mentions that she enjoys photography, and Ben says that he likes taking pictures too.","They talk about parks and interesting places to visit at weekends. Ben avoids questions that might feel too personal at a first meeting. Instead, he asks about hobbies and local activities. When the family invites him to join a game, he agrees. Before leaving, Ben thanks everyone for making him feel welcome. He is pleased that a simple conversation helped him relax."],"questions":[["Whose family does Ben meet?",["Ana's","His own","Leo's"],0],["Which hobby do Ben and one cousin share?",["Cooking","Photography","Football"],1],["What kinds of questions does Ben avoid?",["Questions about hobbies","Questions about parks","Very personal questions"],2],["How does he end the visit?",["He asks for money","He thanks the family","He leaves without speaking"],1]]},"dialogue":[["Ana","Ben, this is my cousin Rosa.","Бен, это моя двоюродная сестра Роза."],["Ben","It's nice to meet you.","Приятно познакомиться."],["Rosa","Nice to meet you too. Do you live nearby?","Взаимно. Ты живёшь поблизости?"],["Ben","Yes, I do. I live near the park.","Да. Живу возле парка."],["Rosa","What do you like doing at weekends?","Чем любишь заниматься по выходным?"],["Ben","I enjoy taking photos. How about you?","Люблю фотографировать. А ты?"],["Rosa","I like photography too.","Я тоже люблю фотографию."],["Ben","That's great. We have that in common.","Здорово. У нас общее увлечение."]],"listening":["What hobby do they share?",["Swimming","Photography","Dancing"],1],"speaking":["Introduce yourself to a fictional friend's family in three sentences.","Ask four friendly present-simple questions about hobbies.","Give two short answers using do and does.","Describe a shared interest that could start a conversation.","Role-play thanking someone for a welcoming visit."],"writing":["Write a short introduction for a fictional family gathering.","Write five non-intrusive questions for someone you have just met.","Write a thank-you message after a friendly visit."],"model":"Hi, I'm Ben. It's nice to meet you. I live nearby and enjoy taking photos at weekends. Ana told me that you like photography too. Thanks for inviting me.","profile":"extended-v1"},{"id":"mission-v2-099","day":99,"level":"A2","title":"Printing a document at a copy shop","ru":"Печать документа в копицентре","goal":"Объяснить параметры печати, выбрать количество экземпляров и проверить результат.","version":1,"quality":"authored-not-independently-reviewed","grammar":{"title":"Would like + noun / to-infinitive","rule":"Would like — вежливое выражение желания. После него можно поставить существительное или to + глагол. В вопросе: Would you like…? I would like to print…","pattern":"I'd like two copies; I'd like to print this file.","example":"Would you like it in colour?","pitfall":"Не путай I'd like printing с I'd like to print в конкретной просьбе.","exercises":[["choice","I'd like ___ print this document.",["to","for","at"],0,"Would like + to-infinitive."],["type","Complete: I'd like ___ (two/second) copies, please.",["two"],"Two is the quantity."],["order","Составь: Я хотел бы распечатать этот файл.",["file","this","print","to","like","would","I"],"I would like to print this file","Would like + to + verb."],["choice","Would you like it ___ colour?",["in","on","with to"],0,"In colour."],["type","Complete: We'd like to ___ (check) the first page.",["check"],"To + base verb."],["order","Составь: Хотели бы вы один экземпляр?",["copy","one","like","you","Would"],"Would you like one copy","Would + subject + like."]]},"words":[["a copy shop","копицентр"],["a double-sided print","двусторонняя печать"],["a black-and-white copy","чёрно-белая копия"],["a colour printout","цветная распечатка"],["a page range","диапазон страниц"],["a paper size","формат бумаги"],["a print preview","предварительный просмотр печати"],["a spare copy","запасной экземпляр"],["a print quality setting","настройка качества печати"],["a printed attachment","распечатанное приложение"]],"phrases":[["I'd like to print this document, please.","Я хотел бы распечатать этот документ."],["Could you print it double-sided?","Можете напечатать с двух сторон?"],["Two copies will be enough.","Двух экземпляров будет достаточно."],["I only need pages three to five.","Мне нужны только страницы с третьей по пятую."],["Could I see the print preview?","Могу увидеть предварительный просмотр?"],["Please print the first page in colour.","Напечатайте первую страницу в цвете."],["The other pages can be black and white.","Остальные страницы могут быть чёрно-белыми."],["What paper size is this?","Какой это формат бумаги?"],["Can we check the first copy before printing the rest?","Можно проверить первый экземпляр перед печатью остальных?"],["Everything looks correct now.","Теперь всё выглядит правильно."]],"reading":{"title":"Printing a document at a copy shop","paragraphs":["Maya needs two printed copies of a five-page document for a course. She visits a copy shop with the file on her phone. The first page contains a small colour diagram, but the other pages are only text. Maya asks the assistant to print the first page in colour and the remaining pages in black and white. She also asks whether double-sided printing is available.","The assistant shows her the print preview and explains that the diagram will remain clear at the chosen paper size. Maya requests one test copy before printing the second one. She checks that all five pages are present and that the diagram is readable. After confirming the result, she asks for the second copy and pays for the completed order."],"questions":[["How many copies does Maya need?",["One","Two","Five"],1],["Which page needs colour?",["The first","The last","Every page"],0],["Why does she request a test copy?",["To change the document title","To avoid paying","To check the result"],2],["How many pages are in the document?",["Three","Five","Ten"],1]]},"dialogue":[["Maya","I'd like two copies of this file, please.","Мне нужны два экземпляра этого файла."],["Assistant","Would you like colour or black and white?","Цветные или чёрно-белые?"],["Maya","The first page in colour, the rest in black and white.","Первую страницу в цвете, остальные чёрно-белые."],["Assistant","Would you like them double-sided?","С двусторонней печатью?"],["Maya","Yes, please. Can I check the first copy?","Да, пожалуйста. Можно проверить первый экземпляр?"],["Assistant","Of course. Here is the print preview.","Конечно. Вот предварительный просмотр."],["Maya","The pages look correct.","Страницы выглядят правильно."],["Assistant","Great. I'll print the second copy now.","Отлично. Сейчас напечатаю второй экземпляр."]],"listening":["What does Maya want to check before the second copy?",["The first copy","The price of a new phone","The shop's address"],0],"speaking":["Ask for a fictional document to be printed with three parameters.","Explain which pages need colour and which do not.","Request a preview before confirming a print job.","Give two polite requests with would like to.","Role-play checking page count and readability."],"writing":["Write a copy shop order for an imaginary five-page file.","Write a short correction after finding a missing page in a test print.","Write a confirmation of the final printing parameters."],"model":"Hello, I'd like two double-sided copies of this five-page document. Please print page one in colour and the other pages in black and white. Could I check the first copy before you print the second one?","profile":"extended-v1"},{"id":"mission-v2-129","day":129,"level":"B1","title":"Requesting leave with a handover","ru":"Отпуск с передачей дел","goal":"Запросить согласование отсутствия, предложить передачу задач и отделить запрос от подтверждения.","version":1,"quality":"authored-not-independently-reviewed","grammar":{"title":"Present perfect and past simple in status updates","rule":"Present Perfect (have/has + V3) сообщает о текущем результате без указания законченного момента; Past Simple описывает событие в конкретное время. Yet, already часто сопровождают Present Perfect; yesterday, last week — Past Simple.","pattern":"I've drafted the handover; I sent the request yesterday.","example":"The manager hasn't approved it yet.","pitfall":"Не используй have sent yesterday для законченного события.","exercises":[["choice","I ___ the request yesterday.",["sent","have sent","has sent"],0,"Yesterday uses past simple."],["type","Complete: The manager hasn't ___ (approve) the request yet.",["approved"],"Hasn't + past participle."],["order","Составь: Я уже подготовил записку.",["note","the","prepared","already","have","I"],"I have already prepared the note","Already follows have."],["choice","We ___ the backup arrangements, so we can review them now.",["have confirmed","confirmed yesterday tomorrow","has confirm"],0,"Present perfect describes the current result."],["type","Complete: She ___ (send) the email last Friday.",["sent"],"Last Friday refers to a finished time."],["order","Составь: Мы ещё не получили подтверждение.",["yet","confirmation","received","not","have","We"],"We have not received confirmation yet","Have not + V3 + yet."]]},"words":[["a leave request","заявка на отпуск"],["a handover checklist","перечень передачи дел"],["a pending approval","ожидаемое согласование"],["a cover contact","контакт замещающего сотрудника"],["an urgent item","срочная задача"],["a planned absence","запланированное отсутствие"],["a continuity arrangement","порядок обеспечения непрерывности работы"],["a task owner","ответственный за задачу"],["a return date","дата возвращения"],["a leave confirmation","подтверждение отпуска"]],"phrases":[["I'd like to request leave for these dates.","Хотел бы запросить отпуск на эти даты."],["I've drafted a handover checklist.","Я подготовил перечень передачи дел."],["The request hasn't been approved yet.","Заявка ещё не согласована."],["I sent the proposed dates yesterday.","Я отправил предлагаемые даты вчера."],["Please confirm who will cover the urgent items.","Подтвердите, кто будет заниматься срочными задачами."],["I'll record the current status of each task.","Зафиксирую текущее состояние каждой задачи."],["The arrangements are subject to approval.","Договорённости требуют согласования."],["My proposed return date is Monday.","Предполагаемая дата возвращения — понедельник."],["Can we review the outstanding tasks before I leave?","Можем проверить незакрытые задачи перед моим уходом?"],["I'll update the team once the dates are confirmed.","Сообщу команде после подтверждения дат."]],"reading":{"title":"Requesting leave with a handover","paragraphs":["Sam wants to request a short period of annual leave next month. Before submitting the request, he reviews the tasks that may still be open during his absence. He identifies two items that need another team member's attention and prepares a handover checklist with the current status, the next action and the proposed cover contact for each one. He does not assume that his colleague has agreed to provide cover.","Sam sends the proposed dates to his manager and asks whether the arrangements are suitable. The manager confirms that the request has been received, but explains that approval depends on the team's schedule. Sam keeps the dates marked as pending. Once the manager and the cover contact have confirmed the arrangements, he updates the shared calendar and sends the team a final handover note."],"questions":[["What does Sam prepare before requesting leave?",["A handover checklist","A new contract","A travel advertisement"],0],["How many items may need cover?",["One","Two","Five"],1],["What does the manager initially confirm?",["Final approval","A cancellation","Receipt of the request"],2],["When does Sam update the shared calendar?",["Before sending the request","After arrangements are confirmed","Without telling the team"],1]]},"dialogue":[["Sam","I'd like to request leave for the first week of next month.","Хочу запросить отпуск на первую неделю следующего месяца."],["Manager","Have you reviewed the outstanding tasks?","Ты проверил незакрытые задачи?"],["Sam","Yes, I've drafted a handover checklist.","Да, подготовил перечень передачи дел."],["Manager","Has the proposed cover contact agreed?","Предложенный замещающий сотрудник согласился?"],["Sam","Not yet. I'll ask for confirmation today.","Пока нет. Сегодня запрошу подтверждение."],["Manager","Good. The dates remain pending for now.","Хорошо. Пока даты ожидают согласования."],["Sam","Understood. I'll update the team when everything is confirmed.","Понял. Сообщу команде после подтверждения."],["Manager","Let's review the checklist tomorrow.","Давай проверим перечень завтра."]],"listening":["What has not yet been confirmed?",["The proposed cover contact","The existence of a checklist","Sam's name"],0],"speaking":["Explain a proposed absence without presenting it as approved.","Report three handover actions using present perfect and past simple appropriately.","Ask a colleague whether they can cover an urgent item.","Summarise the status of an imaginary leave request.","Role-play confirming the return date and handover ownership."],"writing":["Write a professional leave request with proposed dates and a handover outline.","Draft a short task handover with status and a proposed owner.","Write an update distinguishing received, pending and approved leave."],"model":"I'd like to request leave from 3 to 7 May. I've prepared a handover checklist covering two outstanding items, but the proposed cover contact has not yet confirmed availability. Please let me know whether the dates and arrangements can be approved.","profile":"extended-v1"},{"id":"mission-v2-159","day":159,"level":"B1","title":"Explaining why a song matters","ru":"Почему песня запомнилась","goal":"Обсудить музыкальные впечатления, описать атмосферу и выразить личную реакцию без цитирования текста.","version":1,"quality":"authored-not-independently-reviewed","grammar":{"title":"Gerunds after enjoy / avoid / keep","rule":"После enjoy, avoid, keep часто используется форма -ing. После want, decide — to + начальная форма. Remember + -ing и remember + to имеют разные значения.","pattern":"I enjoy listening; I decided to listen again.","example":"She keeps returning to the same album.","pitfall":"Не употребляй enjoy to listen в стандартной речи.","exercises":[["choice","I enjoy ___ to acoustic music.",["listening","to listen","listen"],0,"Enjoy + -ing."],["type","Complete: He decided ___ (listen) to the whole album.",["to listen"],"Decide + to-infinitive."],["order","Составь: Она продолжает слушать эту песню.",["song","this","to","listening","keeps","She"],"She keeps listening to this song","Keep + -ing."],["choice","They avoid ___ during the quiet part.",["talking","to talk","talk"],0,"Avoid + gerund."],["type","Complete: I enjoy ___ (discover) new performers.",["discovering"],"Enjoy + gerund."],["order","Составь: Мы решили обсудить мелодию.",["melody","the","discuss","to","decided","We"],"We decided to discuss the melody","Decide + to-infinitive."]]},"words":[["a memorable melody","запоминающаяся мелодия"],["an acoustic arrangement","акустическая аранжировка"],["a vocal performance","вокальное исполнение"],["an opening verse","первый куплет"],["a repeated chorus","повторяющийся припев"],["a gradual build-up","постепенное нарастание"],["a musical contrast","музыкальный контраст"],["an emotional association","эмоциональная ассоциация"],["a listening habit","привычка слушать музыку"],["a live performance","живое выступление"]],"phrases":[["I enjoy listening to this kind of music when I need to concentrate.","Мне нравится слушать такую музыку, когда нужно сосредоточиться."],["The arrangement starts quietly and builds gradually.","Аранжировка начинается тихо и постепенно нарастает."],["The melody is easy to remember.","Мелодия легко запоминается."],["The vocal performance gives the song a different mood.","Вокальное исполнение придаёт песне другое настроение."],["I associate it with a particular period in my life.","Она ассоциируется у меня с определённым периодом жизни."],["We can discuss the meaning without quoting the lyrics.","Можем обсудить смысл без цитирования текста."],["The live version sounds more energetic to me.","Живая версия кажется мне более энергичной."],["I decided to listen to the entire album.","Я решил послушать весь альбом."],["Different listeners may interpret it differently.","Разные слушатели могут воспринимать её по-разному."],["What makes this piece memorable for you?","Что делает эту композицию запоминающейся для тебя?"]],"reading":{"title":"Explaining why a song matters","paragraphs":["A small music club chooses a fictional song for its weekly discussion. The recording begins with a quiet guitar and gradually introduces a fuller arrangement. One listener enjoys the calm opening because it reminds him of long journeys. Another prefers the final section, where the vocal performance becomes more energetic. Neither listener claims that the song must have the same meaning for everyone.","The club leader asks each person to explain a musical feature and their own reaction without repeating the lyrics. This makes the discussion more useful for people who have not heard the recording. The members compare the studio arrangement with an imaginary live version and explain what changes in the atmosphere. They decide to listen to the full album before the next meeting."],"questions":[["What instrument begins the fictional recording?",["Piano","Guitar","Trumpet"],1],["What does one listener associate with the calm opening?",["Long journeys","A new job","A sporting event"],0],["What does the leader ask them not to repeat?",["The title","Their own opinions","The lyrics"],2],["What do they decide to listen to next?",["A news broadcast","The full album","A different radio station"],1]]},"dialogue":[["Leo","I enjoy listening to the quiet opening.","Мне нравится слушать тихое начало."],["Nina","I prefer the energetic final section.","Мне больше нравится энергичная финальная часть."],["Leo","What makes it memorable for you?","Чем она тебе запомнилась?"],["Nina","The arrangement builds gradually.","Аранжировка постепенно нарастает."],["Leo","I associate the melody with long journeys.","У меня мелодия ассоциируется с долгими поездками."],["Nina","That's interesting. We interpret it differently.","Интересно. Мы воспринимаем её по-разному."],["Leo","Shall we listen to the entire album?","Послушаем весь альбом?"],["Nina","Yes, let's discuss it next week.","Да, обсудим его на следующей неделе."]],"listening":["What does Nina prefer?",["The quiet opening","The energetic final section","The album cover"],1],"speaking":["Describe the mood of a fictional song using musical features.","Explain a personal musical association without quoting lyrics.","Use enjoy, keep and decide in three different sentences.","Compare an imaginary studio and live recording.","Ask a friend what makes a melody memorable for them."],"writing":["Write a short review of a fictional song focusing on arrangement and mood.","Write a paragraph comparing two listeners' interpretations.","Write a message recommending an imaginary album without making factual claims about a real performer."],"model":"I enjoy listening to the quiet opening, which gradually develops into a fuller arrangement. The melody reminds me of travelling, while another listener may experience it differently. I decided to listen to the rest of the album before forming a wider opinion.","profile":"extended-v1"},{"id":"mission-v2-189","day":189,"level":"B1","title":"The donation collection inventory","ru":"Учёт собранных пожертвований","goal":"Составить прозрачную запись о передаче вещей, уточнить расхождения и подтвердить полученное.","version":1,"quality":"authored-not-independently-reviewed","grammar":{"title":"Past simple passive","rule":"Past Simple Passive: was/were + V3. Подходит для завершённых действий в прошлом, если важно что произошло с объектом. Согласуй was/were с подлежащим.","pattern":"The boxes were counted yesterday.","example":"The list was signed at the collection point.","pitfall":"Не говори The boxes was counted.","exercises":[["choice","The donated boxes ___ checked yesterday.",["were","was","have"],0,"Boxes is plural."],["type","Complete: The receipt was ___ (sign) at noon.",["signed"],"Was + past participle."],["order","Составь: Список был обновлён вчера.",["yesterday","updated","was","list","The"],"The list was updated yesterday","Was + V3."],["choice","Two bags ___ delivered on Friday.",["were","was","is"],0,"Use were with plural bags."],["type","Complete: The missing entry was ___ (add) after review.",["added"],"Passive past uses V3."],["order","Составь: Вещи были пересчитаны дважды.",["twice","counted","were","items","The"],"The items were counted twice","Were + past participle."]]},"words":[["a donation inventory","ведомость пожертвований"],["a collection point","пункт сбора"],["a sealed carton","запечатанная коробка"],["an item count","количество предметов"],["a receipt acknowledgment","подтверждение получения"],["a handover record","акт передачи"],["a discrepancy entry","запись о расхождении"],["a receiving volunteer","принимающий волонтёр"],["a distribution list","список распределения"],["a donation category","категория пожертвования"]],"phrases":[["The boxes were counted at the collection point.","Коробки пересчитали в пункте сбора."],["The receiving volunteer signed the handover record.","Принимающий волонтёр подписал запись о передаче."],["One carton was missing from the original list.","Одной коробки не было в исходном списке."],["Please record the actual item count.","Зафиксируйте фактическое количество предметов."],["The discrepancy was reviewed before the record was updated.","Расхождение проверили до обновления записи."],["We should retain both versions of the list.","Следует сохранить обе версии списка."],["The goods were received, but distribution is still pending.","Вещи получены, но распределение ещё ожидается."],["Could you confirm the number of sealed cartons?","Можете подтвердить количество запечатанных коробок?"],["The acknowledgment does not prove final delivery to recipients.","Подтверждение не доказывает окончательную доставку получателям."],["We have recorded the correction and its reason.","Мы зафиксировали исправление и его причину."]],"reading":{"title":"The donation collection inventory","paragraphs":["A community group organises a fictional collection of books and clothes. At the end of the day, the volunteers prepare a handover record for the receiving organisation. The list shows twelve cartons, but thirteen are present at the collection point. The volunteers do not change the total without checking where the extra carton came from. They compare the written entries with the original collection notes.","One late donation was recorded on a separate sheet but was not included in the main total. After the discrepancy is explained, the corrected list is signed by the receiving volunteer. Both versions and the reason for the correction are retained. The organisers report that thirteen cartons were received, but they make no claim that the items have already reached their final recipients."],"questions":[["How many cartons are present?",["Twelve","Thirteen","Ten"],1],["What caused the difference?",["A late donation was recorded separately","A confirmed theft","A broken vehicle"],0],["Who signs the corrected list?",["A random visitor","The donor's neighbour","The receiving volunteer"],2],["What remains unconfirmed?",["The number received","Final distribution to recipients","The existence of the corrected list"],1]]},"dialogue":[["Volunteer","The list shows twelve cartons, but thirteen are here.","В списке двенадцать коробок, но здесь тринадцать."],["Coordinator","Was the late donation recorded separately?","Позднее пожертвование записали отдельно?"],["Volunteer","Yes, it was added to a separate sheet.","Да, его добавили в отдельный лист."],["Coordinator","Let's compare both records before changing the total.","Сравним обе записи перед изменением количества."],["Volunteer","The discrepancy is now explained.","Теперь расхождение объяснено."],["Coordinator","Please keep both versions and the correction note.","Сохрани обе версии и примечание об исправлении."],["Receiver","Thirteen cartons were received.","Получено тринадцать коробок."],["Coordinator","Thank you. Distribution is still pending.","Спасибо. Распределение ещё ожидается."]],"listening":["How many cartons were received?",["Eleven","Twelve","Thirteen"],2],"speaking":["Summarise a fictional donation handover using past simple passive.","Explain why a difference in item count should be investigated.","Distinguish confirmed receipt from final delivery.","Ask for a correction note to be attached to a record.","Role-play reporting a discrepancy without accusing a volunteer."],"writing":["Write a handover record with a confirmed quantity and an unresolved item.","Write a brief explanation of a corrected inventory count.","Write a public update distinguishing receipt from distribution."],"model":"Thirteen cartons were received at the collection point. The original list showed twelve because one late donation was recorded separately. The discrepancy was reviewed and the corrected list was signed. Distribution to the final recipients remains pending.","profile":"extended-v1"},{"id":"mission-v2-219","day":219,"level":"B2","title":"The contract with an unclear scope","ru":"Договор с неоднозначным объёмом работ","goal":"Уточнить включённые и исключённые результаты, согласовать критерии приёмки без правовых утверждений.","version":1,"quality":"authored-not-independently-reviewed","grammar":{"title":"Noun clauses with whether and what","rule":"Whether вводит альтернативу да/нет; what — содержание или неизвестный элемент. Внутренний порядок слов утвердительный. В деловом письме уточняй предмет, а не только наличие согласия.","pattern":"We need to establish whether revisions are included and what counts as a revision.","example":"Please clarify what the agreed scope covers.","pitfall":"Не пиши what does the scope cover внутри придаточного.","exercises":[["choice","We need to establish ___ the extra review is included.",["whether","what does","where did"],0,"Whether introduces an embedded yes/no question."],["type","Complete: Please clarify ___ (what / the price / includes).",["what the price includes"],"Statement word order."],["order","Составь: Нам нужно уточнить что включает объём работ.",["includes","scope","the","what","clarify","to","need","We"],"We need to clarify what the scope includes","Embedded clause follows statement order."],["choice","It is unclear ___ additional formats require approval.",["whether","what does","which did"],0,"Whether marks the unresolved yes/no issue."],["type","Complete: Explain ___ (what / the client / expects) at delivery.",["what the client expects"],"What + subject + verb."],["order","Составь: Мы не знаем включены ли исправления.",["included","are","revisions","whether","know","not","do","We"],"We do not know whether revisions are included","Whether + statement word order."]]},"words":[["a scope boundary","граница объёма работ"],["an acceptance criterion","критерий приёмки"],["an excluded deliverable","результат вне объёма работ"],["a revision allowance","допустимое количество исправлений"],["a change request","запрос на изменение"],["a scope clarification","уточнение объёма работ"],["an ambiguous clause","неоднозначное положение"],["a delivery format","формат результата"],["an approval dependency","зависимость от согласования"],["a documented agreement","зафиксированная договорённость"]],"phrases":[["We need to establish what is included in the agreed scope.","Нужно установить, что входит в согласованный объём работ."],["It is unclear whether an additional review is included.","Неясно, входит ли дополнительная проверка."],["Please define what counts as an accepted deliverable.","Определите, что считается принятым результатом."],["The proposed change falls outside the current description.","Предлагаемое изменение выходит за рамки текущего описания."],["We should clarify the boundary before proceeding.","Следует уточнить границу до продолжения."],["A documented change request would make the decision traceable.","Зафиксированный запрос на изменение обеспечит прослеживаемость решения."],["The acceptance criteria should be agreed in advance.","Критерии приёмки нужно согласовать заранее."],["Please distinguish a correction from an additional feature.","Разграничьте исправление и дополнительную функцию."],["This remains a proposed clarification, not a confirmed amendment.","Это предлагаемое уточнение, а не подтверждённое изменение."],["We can proceed once the revised scope is confirmed.","Можем продолжить после подтверждения пересмотренного объёма."]],"reading":{"title":"The contract with an unclear scope","paragraphs":["A fictional design team agrees to produce a set of training illustrations for a client. The written description specifies the number of illustrations and their delivery date, but it does not state whether editable source files or additional revisions are included. Both sides interpret the wording differently. Rather than assuming that one interpretation is automatically correct, the project coordinator identifies the exact questions that require clarification.","She proposes a written scope note that distinguishes the agreed deliverables, excluded items, acceptance criteria and any requested changes. The client and the design team review the note together before confirming it. The coordinator also explains that an additional feature should not be confused with correcting an error in the agreed deliverable. This is a communication exercise about defining project expectations, not an assessment of legal rights under any actual contract."],"questions":[["What is ambiguous?",["The number of illustrations","Whether editable sources and extra revisions are included","The client's name"],1],["What does the coordinator propose?",["A written scope note","An immediate cancellation","An unrecorded verbal assumption"],0],["What distinction does she make?",["Between two colours","Between two dates","Between an error correction and an extra feature"],2],["When does the note become confirmed?",["Before either side reads it","After both sides review and confirm it","Automatically when it is drafted"],1]]},"dialogue":[["Client","We expected editable source files as well.","Мы ожидали также редактируемые исходники."],["Coordinator","The current description doesn't establish whether they're included.","Текущее описание не устанавливает, входят ли они."],["Designer","Could we define the deliverables and acceptance criteria precisely?","Можем точно определить результаты и критерии приёмки?"],["Client","Yes. We also need to clarify what counts as a revision.","Да. Нужно уточнить, что считается исправлением."],["Coordinator","I'll draft a scope note for both sides to review.","Подготовлю записку об объёме для проверки обеими сторонами."],["Designer","Let's distinguish corrections from additional features.","Разграничим исправления и дополнительные функции."],["Client","That will help us agree on the final delivery.","Это поможет согласовать итоговую передачу."],["Coordinator","The clarification remains proposed until both sides confirm it.","Уточнение остаётся предложением до подтверждения обеими сторонами."]],"listening":["What remains proposed until confirmation?",["The scope clarification","The existing number of illustrations","The fact that a meeting occurred"],0],"speaking":["Explain the difference between an agreed deliverable and an excluded item.","Ask three embedded questions about a fictional project's scope.","Define measurable acceptance criteria for a simple fictional illustration set.","Summarise both sides' interpretations without assigning blame.","Role-play confirming a proposed change rather than assuming it is approved."],"writing":["Write a scope clarification request with two unresolved questions.","Draft a fictional acceptance checklist separating required and optional items.","Write a neutral summary of a proposed scope note pending confirmation."],"model":"The current description specifies the illustration count and deadline but does not establish whether editable source files are included. Please clarify what counts as an accepted deliverable and what constitutes an additional feature. The proposed scope note remains subject to confirmation by both parties.","profile":"extended-v1"},{"id":"mission-v2-249","day":249,"level":"B2","title":"The protection configuration revision request","ru":"Запрос на изменение редакции конфигурации РЗА","goal":"Описать статус запроса, отличить предложение от разрешения и сформулировать требования к документальным доказательствам.","version":1,"quality":"authored-not-independently-reviewed","grammar":{"title":"Modal passive and perfect passive","rule":"Modal + be + V3 expresses requirement or possibility in passive voice; modal + have been + V3 describes a possible/required earlier action, depending on context. Separate must be reviewed from has been reviewed.","pattern":"The request must be reviewed; The revision may have been superseded.","example":"The configuration change must be authorised before implementation.","pitfall":"Must be approved не означает, что одобрение уже получено.","exercises":[["choice","The proposed revision must ___ reviewed by the authorised owner.",["be","been","being"],0,"Modal passive: must be + V3."],["type","Complete: The document may ___ (have / be / supersede) earlier.",["have been superseded"],"Modal perfect passive."],["order","Составь: Запрос должен быть рассмотрен.",["reviewed","be","must","request","The"],"The request must be reviewed","Must be + past participle."],["choice","The record ___ approved yet, so the status is pending.",["has not been","must be already","have not be"],0,"Has not been approved describes current status."],["type","Complete: The original record should be ___ (retain).",["retained"],"Should be + V3."],["order","Составь: Редакция может быть уже заменена.",["superseded","been","have","may","revision","The"],"The revision may have been superseded","May have been + past participle."]]},"words":[["a configuration revision request","запрос на изменение редакции конфигурации"],["an authorisation record","запись о разрешении"],["a baseline reference","ссылка на базовую редакцию"],["a proposed revision","предлагаемая редакция"],["a review disposition","решение по результатам рассмотрения"],["a configuration register","реестр конфигураций"],["an implementation status","статус внедрения"],["an evidence attachment","приложение с доказательствами"],["a revision traceability record","запись прослеживаемости редакций"],["an unresolved approval dependency","незакрытая зависимость от согласования"]],"phrases":[["The request must be reviewed through the authorised process.","Запрос должен быть рассмотрен в установленном порядке."],["The proposed revision is not an approved configuration.","Предлагаемая редакция не является утверждённой конфигурацией."],["The baseline reference must be retained for traceability.","Ссылку на базовую редакцию нужно сохранить для прослеживаемости."],["The authorisation record has not been provided.","Запись о разрешении не предоставлена."],["Please distinguish the review status from the implementation status.","Разграничьте статус рассмотрения и статус внедрения."],["The earlier revision may have been superseded.","Более ранняя редакция могла быть заменена."],["The evidence attachment remains under review.","Приложение с доказательствами ещё рассматривается."],["No operational action is authorised by this exercise.","Это упражнение не разрешает эксплуатационных действий."],["The register should show the applicable approved revision.","Реестр должен отражать применимую утверждённую редакцию."],["The request remains pending until the required approval is documented.","Запрос остаётся на рассмотрении до документального подтверждения разрешения."]],"reading":{"title":"The protection configuration revision request","paragraphs":["In a fictional relay protection documentation review, an engineer receives a proposed configuration revision request and a supporting note. The request refers to a baseline document, but the accompanying register does not establish whether that baseline is the currently applicable approved revision. The authorisation record is also absent. The engineer therefore cannot report the proposal as approved or implemented merely because the request exists.","She records the exact references, separates the proposed revision from the documented baseline, and requests clarification through the authorised engineering review process. Her status note distinguishes receipt, review, approval and implementation as separate evidence states. The original documents and any clarification must be retained for traceability. This exercise concerns professional English and document status only; it provides no instructions for modifying protection settings or operating equipment."],"questions":[["What is missing?",["The name of the fictional exercise","The authorisation record","Every document reference"],1],["What is not established about the baseline?",["Whether it is the applicable approved revision","Whether it has a title","Whether the proposal exists"],0],["Which states are distinguished?",["Only the creation date","Only the file size","Receipt, review, approval and implementation"],2],["What is the scope of the exercise?",["Operational changes","Written document-status communication","Equipment commissioning instructions"],1]]},"dialogue":[["Engineer","The revision request has been received, but approval is not documented.","Запрос получен, но разрешение не документировано."],["Reviewer","Has the baseline reference been established?","Ссылка на применимую базовую редакцию установлена?"],["Engineer","Not yet. The register is inconclusive.","Пока нет. Реестр не даёт однозначного ответа."],["Reviewer","The request must be reviewed through the authorised process.","Запрос должен быть рассмотрен в установленном порядке."],["Engineer","I'll retain the original references and request clarification.","Сохраню исходные ссылки и запрошу уточнение."],["Reviewer","Make the approval dependency explicit in the status note.","Явно укажи зависимость от разрешения в статусной записке."],["Engineer","Understood. No implementation is confirmed.","Понял. Внедрение не подтверждено."],["Reviewer","Keep those evidence states separate.","Держи эти состояния доказательств раздельно."]],"listening":["Which status is not confirmed?",["Receipt","Existence of a request","Implementation"],2],"speaking":["Describe the evidence state of a fictional configuration revision request.","Use modal passive to state a document review requirement without issuing an operating instruction.","Distinguish receipt, approval and implementation in a professional handover.","Request clarification of a baseline reference through the authorised process.","Explain why a proposed document cannot establish an approved configuration on its own."],"writing":["Write a status note for a fictional unapproved revision request.","Draft an English clarification request for the applicable approved baseline.","Write a short review record separating observations, pending approvals and scope limits."],"model":"The proposed configuration revision request has been received. The applicable approved baseline and the authorisation record have not been established. The request must be reviewed through the authorised engineering process. Receipt does not establish approval or implementation. No operational action is authorised by this document-review exercise.","profile":"extended-v1"},{"id":"mission-v2-279","day":279,"level":"B2","title":"When two definitions change the debate","ru":"Когда разные определения меняют спор","goal":"Выявить различие в определениях, переформулировать аргументы и согласовать критерии сравнения.","version":1,"quality":"authored-not-independently-reviewed","grammar":{"title":"Contrastive clauses with whereas / while","rule":"Whereas и while могут противопоставлять два утверждения. While также обозначает время; контекст показывает значение. Whereas особенно полезно для сопоставления определений. Не подменяй контраст причинной связью.","pattern":"One definition concerns attendance, whereas the other concerns active participation.","example":"While both teams use the same label, they measure different outcomes.","pitfall":"После whereas нужен полный clause.","exercises":[["choice","One team counts attendance, ___ the other counts completed contributions.",["whereas","because of","despite of"],0,"Whereas contrasts two complete clauses."],["type","Complete with whereas: The first metric counts visits, ___ the second counts completed tasks.",["whereas"],"Whereas introduces a contrast."],["order","Составь: Одна группа измеряет скорость тогда как другая измеряет точность.",["accuracy","measures","other","the","whereas","speed","measures","group","One"],"One group measures speed whereas the other measures accuracy","Whereas connects contrasting clauses."],["choice","___ both sides use the same word, their definitions differ.",["While","Despite of","Because of that"],0,"While can express contrast."],["type","Complete with while: ___ both measures are useful, they answer different questions.",["while"],"While introduces a concessive contrast."],["order","Составь: Первый показатель измеряет охват тогда как второй измеряет глубину.",["depth","measures","second","the","whereas","reach","measures","metric","first","The"],"The first metric measures reach whereas the second measures depth","Whereas contrasts metrics."]]},"words":[["an operational definition","операциональное определение"],["a measurement criterion","критерий измерения"],["a conceptual distinction","понятийное различие"],["shared terminology","общая терминология"],["a comparable outcome","сопоставимый результат"],["a proxy measure","косвенный показатель"],["a boundary condition","граничное условие"],["an interpretation gap","расхождение интерпретаций"],["a definitional disagreement","разногласие в определениях"],["a common reference point","общая точка отсчёта"]],"phrases":[["The disagreement partly reflects different definitions.","Разногласие частично связано с разными определениями."],["Both teams use the same label for different outcomes.","Обе команды используют один термин для разных результатов."],["We should establish an operational definition before comparing scores.","Следует установить операциональное определение до сравнения оценок."],["One measure counts attendance, whereas the other counts active contributions.","Один показатель учитывает посещаемость, другой — активное участие."],["The proxy measure does not capture every aspect of the concept.","Косвенный показатель не охватывает все стороны понятия."],["The apparent contradiction may disappear once the terms are clarified.","Кажущееся противоречие может исчезнуть после уточнения терминов."],["Can we identify a common reference point?","Можем определить общую точку отсчёта?"],["The two results are not directly comparable under the current definitions.","Эти два результата не сопоставимы напрямую при текущих определениях."],["A useful definition should specify what is counted and what is excluded.","Полезное определение должно указывать, что учитывается и что исключено."],["The conclusion should state which definition it relies on.","Вывод должен указывать, на какое определение он опирается."]],"reading":{"title":"When two definitions change the debate","paragraphs":["Two teams evaluate participation in a fictional training programme. One reports a high participation rate because it counts everyone who attends at least one session. The other reports a lower rate because it counts only learners who complete a practical contribution. At first, the teams treat their results as contradictory. A reviewer notices that the same label is being used for two different operational definitions.","She asks the teams to state precisely what each measure includes and excludes. They agree that attendance and active contribution are both useful outcomes, but they should not be compared as if they were identical. The revised report presents the measures separately and explains the questions each one answers. Before the next evaluation, the teams will agree on shared definitions and a common reference period so that any comparison is meaningful."],"questions":[["What does the first team count?",["Only final exam passes","Anyone attending at least one session","Only practical contributions"],1],["What does the second team count?",["Learners completing a practical contribution","All registered learners","All invited people"],0],["Why are the initial results not directly comparable?",["They use the same number","No sessions took place","They use different operational definitions"],2],["What will they agree before the next evaluation?",["A new project name","Shared definitions and a common reference period","A guarantee of identical scores"],1]]},"dialogue":[["Reviewer","Both teams use the word participation, but the definitions differ.","Обе команды используют слово участие, но определения различаются."],["Team A","We count anyone who attends at least one session.","Мы считаем каждого, кто посетил хотя бы одно занятие."],["Team B","We count completed practical contributions.","Мы учитываем завершённые практические работы."],["Reviewer","Both measures are useful, but they answer different questions.","Это полезные показатели, но они отвечают на разные вопросы."],["Team A","So the figures aren't directly comparable?","Значит, цифры нельзя сравнивать напрямую?"],["Reviewer","Not under the current definitions.","Не при текущих определениях."],["Team B","Let's agree on a common reference period.","Согласуем общий период отсчёта."],["Reviewer","And report both outcomes separately.","И представим оба результата отдельно."]],"listening":["What do the teams need to agree on?",["A common reference period","A new building","An identical outcome regardless of evidence"],0],"speaking":["Explain how two operational definitions can produce different results.","Use whereas to contrast attendance and active contribution.","Propose a common reference period for a fictional comparison.","Describe the limits of a proxy measure without dismissing it.","Role-play resolving a definitional disagreement before debating the figures."],"writing":["Write a revised evaluation paragraph distinguishing two metrics.","Draft operational definitions for attendance and active contribution.","Write a brief recommendation for a comparable follow-up evaluation."],"model":"One team counts attendance, whereas the other counts completed practical contributions. Both outcomes are informative, but the reported rates are not directly comparable. The evaluation should present each measure separately and specify its definition and reference period. A shared definition is needed for future comparisons.","profile":"extended-v1"}]);
